      "note": "表示移动目的；名词需表示可进行的动作或活动，不能把任意名词直接接在「に行く／来る」前。",
      "contrast": "ます形去ます＋に行く表示去的目的；去的地点用へ／に（図書館へ本を借りに行く）。",
      "promptZh": "去图书馆借书。",
      "answerJa": "図書館へ本を借りに行きます。",
