      "note": "用于礼貌、美化或敬语表达；不是所有词都能随意加。也有习惯接「お」的汉语词，如「お電話」「お時間」「お食事」。",
      "contrast": "お多接和语词（お名前），ご多接汉语词（ご家族）；也有习惯用お的汉语词（お電話）。",
