      "formation": "Vて形 + おく",
      "note": "表示为将来做准备，或维持某状态。口语常缩成〜とく。",
      "contrast": "ておく：为以后事先做好、或保持原状；てある：（有人做好后）现在的状态。",
      "promptZh": "旅行前先预约好酒店。",
