      "note": "较书面、较客观地表示比喻或根据情况作出的推测。な形容词和名词只有肯定非过去形分别使用「な／の」，如「静かなようだ／学生のようだ」；过去或否定形直接接「ようだ」，如「静かだったようだ／学生ではないようだ」。",
      "contrast": "ようだ较书面，名词要加の（雨のようだ）；みたいだ是口语，名词直接接（雨みたいだ）。",
