      "note": "用于转述听到或读到的信息，比「そうだ」更书面、客观。",
      "contrast": "ということだ：转述听到的信息（较书面）；そうだ：一般的传闻。",
      "promptZh": "听说田中下个月要辞职。",
      "answerJa": "田中さんは来月、会社を辞めるということです。",
