      "contrast": "N上（じょう）＝在……方面（书面，接汉语名词）；Nの上で＝在……上（较口语）；V辞書形 + うえで（第6集）＝在做……的过程中。",
      "promptZh": "让孩子玩游戏玩到深夜，在教育上是不好的。",
      "answerJa": "子供に夜遅くまでゲームをさせるのは、教育上よくありません。",
