      "contrast": "だけあって＝不愧是（正面评价）；だけに（第32集）＝正因为……所以更（好坏都可以）；にしては（N3）＝作为……来说（与预想不符）。",
      "promptZh": "不愧是专业厨师，每道菜都很好吃。",
