      "note": "比「にしても」更书面：①即使……也（让步）；②「AにしろBにしろ」＝无论A还是B。口语也说「にしたって」。",
      "contrast": "にしろ・にせよ≈にしても（N3），更书面；たとえ〜ても（N3）＝即使……也；にかかわらず（第53集）＝不论……。",
      "promptZh": "不管有什么理由，暴力都是不对的。",
      "answerJa": "どんな理由があるにせよ、暴力はいけない。",
